#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
template <int TILE_H, int TILE_W>
__global__ void conv2d_kernel(
    const bfloat16_t* __restrict__ X,
    const bfloat16_t* __restrict__ W,
    bfloat16_t* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int KH, int KW,
    int Hout, int Wout)
{
  extern __shared__ unsigned char smem_raw[];
  bfloat16_t* sW_ptr = reinterpret_cast<bfloat16_t*>(smem_raw);
  const int SH = TILE_H + KH - 1;
  const int SW = TILE_W + KW - 1;
  bfloat16_t* sX_ptr = sW_ptr + (Cout * Cin * KH * KW);
  // Shared-memory tensors via CuTe
  auto sW = make_tensor(make_smem_ptr(sW_ptr),
                         make_shape(Cout, Cin, KH, KW),
                         make_stride(Cin * KH * KW, KH * KW, KW, 1));
  auto sX = make_tensor(make_smem_ptr(sX_ptr),
                         make_shape(Cin, SH, SW),
                         make_stride(SH * SW, SW, 1));
  int n            = blockIdx.z;
  int h_out_start  = blockIdx.y * TILE_H;
  int w_out_start  = blockIdx.x * TILE_W;
  // Global-memory tensors via CuTe
  auto mX = make_tensor(make_gmem_ptr(X + (int64_t)n * Cin * H * Win),
                         make_shape(Cin, H, Win),
                         make_stride((int64_t)H * Win, (int64_t)Win, (int64_t)1));
  auto mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * Cout * Hout * Wout),
                         make_shape(Cout, Hout, Wout),
                         make_stride((int64_t)Hout * Wout, (int64_t)Wout, (int64_t)1));
  auto mW = make_tensor(make_gmem_ptr(W),
                         make_shape(Cout, Cin, KH, KW),
                         make_stride((int64_t)Cin * KH * KW, (int64_t)KH * KW, (int64_t)KW, (int64_t)1));
  const int tid      = threadIdx.y * TILE_W + threadIdx.x;
  const int nthreads = TILE_H * TILE_W;
  // Cooperative load of weights into shared memory (reused by every thread in block)
  const int wtotal = Cout * Cin * KH * KW;
  for (int i = tid; i < wtotal; i += nthreads) {
    int kw   = i % KW;
    int tmp  = i / KW;
    int kh   = tmp % KH;
    tmp     /= KH;
    int cin  = tmp % Cin;
    int cout = tmp / Cin;
    sW(cout, cin, kh, kw) = mW(cout, cin, kh, kw);
  }
  // Cooperative load of the input tile (with halo for the 3x3 stencil) into shared memory
  const int xtotal = Cin * SH * SW;
  for (int i = tid; i < xtotal; i += nthreads) {
    int sw  = i % SW;
    int tmp = i / SW;
    int sh  = tmp % SH;
    int cin = tmp / SH;
    int ih  = h_out_start + sh;
    int iw  = w_out_start + sw;
    bfloat16_t val = bfloat16_t(0.0f);
    if (ih < H && iw < Win) {
      val = mX(cin, ih, iw);
    }
    sX(cin, sh, sw) = val;
  }
  __syncthreads();
  const int ty = threadIdx.y;
  const int tx = threadIdx.x;
  const int oh = h_out_start + ty;
  const int ow = w_out_start + tx;
  if (oh < Hout && ow < Wout) {
    for (int cout = 0; cout < Cout; ++cout) {
      float acc = 0.0f;
      #pragma unroll
      for (int cin = 0; cin < Cin; ++cin) {
        #pragma unroll
        for (int kh = 0; kh < KH; ++kh) {
          #pragma unroll
          for (int kw = 0; kw < KW; ++kw) {
            float xv = float(sX(cin, ty + kh, tx + kw));
            float wv = float(sW(cout, cin, kh, kw));
            acc += xv * wv;
          }
        }
      }
      mY(cout, oh, ow) = bfloat16_t(acc);
    }
  }
}
// Specialized kernel with register blocking: caches the per-thread input-tile
// values (which are independent of the output channel) into registers once,
// then reuses them across the loop over output channels. This removes the
// Cout-fold redundant shared-memory reads of the input tile present in the
// generic kernel above.
template <int TILE_H, int TILE_W, int CIN, int KH, int KW, int REGW>
__global__ void conv2d_kernel_regblock(
    const bfloat16_t* __restrict__ X,
    const bfloat16_t* __restrict__ W,
    bfloat16_t* __restrict__ Y,
    int N, int H, int Win,
    int Cout,
    int Hout, int Wout)
{
  extern __shared__ unsigned char smem_raw[];
  bfloat16_t* sW_ptr = reinterpret_cast<bfloat16_t*>(smem_raw);
  constexpr int SH = TILE_H + KH - 1;
  constexpr int SW = TILE_W * REGW + KW - 1;
  bfloat16_t* sX_ptr = sW_ptr + (Cout * CIN * KH * KW);
  auto sW = make_tensor(make_smem_ptr(sW_ptr),
                         make_shape(Cout, Int<CIN>{}, Int<KH>{}, Int<KW>{}),
                         make_stride(CIN * KH * KW, KH * KW, KW, 1));
  auto sX = make_tensor(make_smem_ptr(sX_ptr),
                         make_shape(Int<CIN>{}, Int<SH>{}, Int<SW>{}),
                         make_stride(SH * SW, SW, 1));
  int n            = blockIdx.z;
  int h_out_start  = blockIdx.y * TILE_H;
  int w_out_start  = blockIdx.x * (TILE_W * REGW);
  auto mX = make_tensor(make_gmem_ptr(X + (int64_t)n * CIN * H * Win),
                         make_shape(Int<CIN>{}, H, Win),
                         make_stride((int64_t)H * Win, (int64_t)Win, (int64_t)1));
  auto mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * Cout * Hout * Wout),
                         make_shape(Cout, Hout, Wout),
                         make_stride((int64_t)Hout * Wout, (int64_t)Wout, (int64_t)1));
  auto mW = make_tensor(make_gmem_ptr(W),
                         make_shape(Cout, Int<CIN>{}, Int<KH>{}, Int<KW>{}),
                         make_stride((int64_t)CIN * KH * KW, (int64_t)KH * KW, (int64_t)KW, (int64_t)1));
  const int tid      = threadIdx.y * TILE_W + threadIdx.x;
  const int nthreads = TILE_H * TILE_W;
  const int wtotal = Cout * CIN * KH * KW;
  for (int i = tid; i < wtotal; i += nthreads) {
    int kw   = i % KW;
    int tmp  = i / KW;
    int kh   = tmp % KH;
    tmp     /= KH;
    int cin  = tmp % CIN;
    int cout = tmp / CIN;
    sW(cout, cin, kh, kw) = mW(cout, cin, kh, kw);
  }
  const int xtotal = CIN * SH * SW;
  for (int i = tid; i < xtotal; i += nthreads) {
    int sw  = i % SW;
    int tmp = i / SW;
    int sh  = tmp % SH;
    int cin = tmp / SH;
    int ih  = h_out_start + sh;
    int iw  = w_out_start + sw;
    bfloat16_t val = bfloat16_t(0.0f);
    if (ih < H && iw < Win) {
      val = mX(cin, ih, iw);
    }
    sX(cin, sh, sw) = val;
  }
  __syncthreads();
  const int ty = threadIdx.y;
  const int tx = threadIdx.x;
  const int oh = h_out_start + ty;
  const int ow_base = w_out_start + tx * REGW;
  if (oh < Hout) {
    // Cache the input-tile values used by this thread into registers once;
    // a single register buffer of width (REGW + KW - 1) covers the sliding
    // window needed for all REGW output columns computed by this thread,
    // enabling reuse of both the input values (across output channels) and
    // the shared-memory weight reads (across the REGW output columns computed
    // per thread), further amortizing shared-memory traffic and increasing
    // arithmetic intensity per thread compared to single-output regblocking.
    float xreg[CIN][KH][REGW + KW - 1];
    #pragma unroll
    for (int cin = 0; cin < CIN; ++cin) {
      #pragma unroll
      for (int kh = 0; kh < KH; ++kh) {
        #pragma unroll
        for (int j = 0; j < REGW + KW - 1; ++j) {
          xreg[cin][kh][j] = float(sX(cin, ty + kh, tx * REGW + j));
        }
      }
    }
    for (int cout = 0; cout < Cout; ++cout) {
      float acc[REGW];
      #pragma unroll
      for (int c = 0; c < REGW; ++c) acc[c] = 0.0f;
      #pragma unroll
      for (int cin = 0; cin < CIN; ++cin) {
        #pragma unroll
        for (int kh = 0; kh < KH; ++kh) {
          #pragma unroll
          for (int kw = 0; kw < KW; ++kw) {
            float wv = float(sW(cout, cin, kh, kw));
            #pragma unroll
            for (int c = 0; c < REGW; ++c) {
              acc[c] += xreg[cin][kh][c + kw] * wv;
            }
          }
        }
      }
      #pragma unroll
      for (int c = 0; c < REGW; ++c) {
        int ow = ow_base + c;
        if (ow < Wout) {
          mY(cout, oh, ow) = bfloat16_t(acc[c]);
        }
      }
    }
  }
}
torch::Tensor conv2d_forward(torch::Tensor x, torch::Tensor weight) {
  TORCH_CHECK(x.is_cuda() && weight.is_cuda(), "x and weight must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kBFloat16, "x must be bfloat16");
  TORCH_CHECK(weight.scalar_type() == at::kBFloat16, "weight must be bfloat16");
  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(weight.dim() == 4, "weight must be [Cout, Cin, KH, KW]");
  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();
  int N    = (int)x_c.size(0);
  int Cin  = (int)x_c.size(1);
  int H    = (int)x_c.size(2);
  int Win  = (int)x_c.size(3);
  int Cout = (int)w_c.size(0);
  TORCH_CHECK((int)w_c.size(1) == Cin, "weight.size(1) must equal Cin");
  int KH   = (int)w_c.size(2);
  int KW   = (int)w_c.size(3);
  int Hout = H - KH + 1;
  int Wout = Win - KW + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size (no padding, stride=1 assumed)");
  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  if (Cin == 3 && KH == 3 && KW == 3) {
    constexpr int TILE_H = 16;
    constexpr int TILE_W = 16;
    constexpr int REGW   = 2;
    dim3 block(TILE_W, TILE_H);
    dim3 grid((Wout + TILE_W * REGW - 1) / (TILE_W * REGW),
              (Hout + TILE_H - 1) / TILE_H,
              N);
    size_t smem_w = (size_t)Cout * Cin * KH * KW * sizeof(bfloat16_t);
    size_t smem_x = (size_t)Cin * (TILE_H + KH - 1) * (TILE_W * REGW + KW - 1) * sizeof(bfloat16_t);
    size_t smem_bytes = smem_w + smem_x;
    conv2d_kernel_regblock<TILE_H, TILE_W, 3, 3, 3, REGW><<<grid, block, smem_bytes, stream>>>(
        reinterpret_cast<const bfloat16_t*>(x_c.data_ptr<at::BFloat16>()),
        reinterpret_cast<const bfloat16_t*>(w_c.data_ptr<at::BFloat16>()),
        reinterpret_cast<bfloat16_t*>(y.data_ptr<at::BFloat16>()),
        N, H, Win, Cout, Hout, Wout);
  } else {
    constexpr int TILE_H = 16;
    constexpr int TILE_W = 16;
    dim3 block(TILE_W, TILE_H);
    dim3 grid((Wout + TILE_W - 1) / TILE_W,
              (Hout + TILE_H - 1) / TILE_H,
              N);
    size_t smem_w = (size_t)Cout * Cin * KH * KW * sizeof(bfloat16_t);
    size_t smem_x = (size_t)Cin * (TILE_H + KH - 1) * (TILE_W + KW - 1) * sizeof(bfloat16_t);
    size_t smem_bytes = smem_w + smem_x;
    conv2d_kernel<TILE_H, TILE_W><<<grid, block, smem_bytes, stream>>>(
        reinterpret_cast<const bfloat16_t*>(x_c.data_ptr<at::BFloat16>()),
        reinterpret_cast<const bfloat16_t*>(w_c.data_ptr<at::BFloat16>()),
        reinterpret_cast<bfloat16_t*>(y.data_ptr<at::BFloat16>()),
        N, Cin, H, Win, Cout, KH, KW, Hout, Wout);
  }
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
